#.libPaths("~/R/x86_64-pc-linux-gnu-library/") #library location
library(dplyr)
library(tidyr)
setwd("~/Desktop/Programs/baypass/")
#####read in *summary_pi_xtx.out output by Baypass###########
#fileprefix="aligned2ACB.indf.sync.filteredbycoverage" #prefix for files, if using
xtxdat=read.table("N75_N225_dec_23_output_summary_pi_xtx.out",header=TRUE)

#####read in list of SNPs generated by Baypass's sync2pooldata R function; the list contains mapping info (i.e. which scaffolds are the SNPs from)##########
snplist=read.table("~/Desktop/Programs/baypass/dec_tests/ecb_cline.sync.filteredbycoverage.snpdet", header=FALSE)
#check that snplist and xtxdat have the same number of rows. They should line up!
 
#####add scaffold positions from above to the Baypass output########
xtxdat2=xtxdat%>%mutate(scaffold=rep(snplist$V1, 1), pos=rep(snplist$V2, 1))

#####simulate data (PODs; see BayPass manual) to find the significance threshold for the Xtx values########
source("~/Desktop/baypass/baypass_2.2/utils/baypass_utils.R") #R scripts came with BayPass
pi.beta.coef=read.table("N75_N225_dec_23_output_summary_beta_params.out",h=T)$Mean
omega=as.matrix(read.table("N75_N225_dec_23_output_mat_omega.out"))
ecb7.dat=geno2YN("../dec_tests/ecb_cline.sync.filteredbycoverage.N75_N225.genobaypass") #.genobaypass file from sync2pooldata()
ecb7.simu=simulate.baypass(omega.mat=omega,nsnp=50000,sample.size=ecb7.dat$NN,beta.pi=pi.beta.coef,pi.maf=0.01,coverage=50,suffix="pods")
#then run BayPass again on this simulated dataset. 
#when done, proceed with the script below.
pod.xtx=read.table("N75_N225.pods_output_summary_pi_xtx.out",header=TRUE)$M_XtX
pod.thresh=quantile(pod.xtx,probs=0.95)

#####filter for SNPs above the 99.99% quantile of PODs########
xtxdat_filtered=xtxdat2%>%filter(M_XtX>=4.625) # check percentile of pods and adjust accordingly
write.table(xtxdat_filtered,file="N75_N225.indf.sync.filteredbycoverage.scalecov_top147_xtx", sep="\t",row.names = FALSE,col.names = FALSE,quote=FALSE)

#####save in BED file format so that significant SNPs can be mapped to .gff file by Bedtools########
xtxdat_filtered2_N=xtxdat_filtered%>%mutate(startpos=pos-1,endpos=pos)%>%select(scaffold,startpos,endpos)
write.table(xtxdat_filtered2_N,file="N75_N225.indf.sync.filteredbycoverage.scalecov_sig_xtx.BED", sep="\t",row.names = FALSE,col.names = FALSE,quote=FALSE)
#I used either 'bedtools intersect' or 'bedtools window' to find the annotations in the .gff file for the SNPs with significant Xtx values in the .BED file generated here






#### plotting: 
pdf("scaffold_532_test.pdf", height = 5, width = 8)
period_cds <- read.table("~/Desktop/baypass/R_analyses/period_cds.txt", header = T)

plot(xtxdat2$pos, xtxdat2$log10.1.pval., pch = 19, cex = 0.5, ylab = "log10 p-value", xlab = "Position on scaffold 532")
rect(xleft = period_cds[1,1], ybottom = 3, ytop = 3.5,xright = period_cds[32,2], col = 'black')
points(xtxdat_filtered$pos, xtxdat_filtered$log10.1.pval., col = "red")
dev.off()



